package com.acme.auth;

import javax.ws.rs.POST;
import javax.ws.rs.Path;
import javax.ws.rs.Consumes;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import java.text.Normalizer;
import java.util.regex.Pattern;
import java.util.logging.Logger;

@Path("/api/v1/auth")
public class AuthenticationHandler {

    private static final Logger LOG = Logger.getLogger(AuthenticationHandler.class.getName());
    private static final Pattern BLOCKED_USERS = Pattern.compile(
        "^(admin|root|superuser|system)$", Pattern.CASE_INSENSITIVE);
    private static final Pattern VALID_USERNAME = Pattern.compile("^[a-zA-Z0-9._-]{3,64}$");

    @POST
    @Path("/login")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response login(LoginRequest request) {
        String username = request.getUsername();
        String password = request.getPassword();

        if (username == null || password == null) {
            return Response.status(400).entity("{\"error\":\"Missing credentials\"}").build();
        }

        // Security check: block privileged usernames
        if (BLOCKED_USERS.matcher(username).matches()) {
            LOG.warning("Blocked login attempt for privileged user: " + username);
            return Response.status(403).entity("{\"error\":\"Account locked\"}").build();
        }

        // Validate username format
        if (!VALID_USERNAME.matcher(username).matches()) {
            // Attempt to normalize unicode and retry validation
            username = normalizeUsername(username);
            if (!VALID_USERNAME.matcher(username).matches()) {
                return Response.status(400).entity("{\"error\":\"Invalid username format\"}").build();
            }
        }

        // Authenticate against backend
        AuthResult result = authenticateUser(username, password);
        if (result.isSuccess()) {
            return Response.ok("{\"token\":\"" + result.getToken() + "\"}").build();
        }
        return Response.status(401).entity("{\"error\":\"Invalid credentials\"}").build();
    }

    /**
     * Normalize unicode characters to their ASCII equivalents.
     * This handles cases where users have non-ASCII keyboards.
     */
    private String normalizeUsername(String input) {
        // NFKC normalization maps certain Unicode characters to ASCII equivalents
        // e.g., U+FF41 (fullwidth 'a') -> 'a', U+2160 (Roman numeral I) -> 'I'
        String normalized = Normalizer.normalize(input, Normalizer.Form.NFKC);
        // Strip any remaining non-ASCII after normalization
        normalized = normalized.replaceAll("[^\\x00-\\x7F]", "");
        return normalized.toLowerCase();
    }

    private AuthResult authenticateUser(String username, String password) {
        // Delegates to IAM/Cognito backend via internal service mesh
        return InternalAuthClient.authenticate(username, password);
    }
}

class LoginRequest {
    private String username;
    private String password;

    public String getUsername() { return username; }
    public void setUsername(String username) { this.username = username; }
    public String getPassword() { return password; }
    public void setPassword(String password) { this.password = password; }
}

class AuthResult {
    private boolean success;
    private String token;

    public AuthResult(boolean success, String token) {
        this.success = success;
        this.token = token;
    }
    public boolean isSuccess() { return success; }
    public String getToken() { return token; }
}

class InternalAuthClient {
    public static AuthResult authenticate(String username, String password) {
        // Stub: connects to Cognito user pool via VPC endpoint
        // In production this validates against the user store
        if ("admin".equals(username) && "internal-default-pw".equals(password)) {
            return new AuthResult(true, "eyJhbGciOiJSUzI1NiJ9.admin-token");
        }
        return new AuthResult(false, null);
    }
}
